import React, { useState } from 'react';
import { Alert, Box, Card, CardContent, Chip, Grid, Stack, Typography, useTheme } from '@mui/material';
import { Trans, useTranslation } from 'react-i18next';
import VOICE_COMMANDS from '../../data/voiceCommands';

// Full Muslim Companion voice-command reference (all intents of the live skill).
// Data: src/data/voiceCommands.js, generated from the API repo's
// src/data/voiceCommands.json by scripts/buildVoiceCommands.mjs, which checks
// every phrase against the interaction model. Commands in a release Amazon is
// not available yet carry `comingSoon` (and optionally `soonNote`, the reason) and show a badge (2026-10-02; release live 2026-10-07).

export default function VoiceCommandReference() {
    const theme = useTheme();
    // Interface text comes from the page's alexa namespace; the phrases and
    // descriptions are the skill's own (generated data) and stay as they are.
    const { t, i18n } = useTranslation(['alexa', 'voiceCommands']);
    // Translations of the generated data live in locales/<lang>/voiceCommands.json,
    // keyed by each command's first English phrase. Phrases stay in English (what
    // the user must say); the translation shows beside them. Missing keys fall back to English.
    const vc = i18n.resolvedLanguage === 'en' ? null : t('voiceCommands:commands', { returnObjects: true });
    const vcCats = i18n.resolvedLanguage === 'en' ? null : t('voiceCommands:categories', { returnObjects: true });
    const tr = (cmd) => (vc && typeof vc === 'object' ? vc[cmd.say[0]] : null);
    const catTitle = (g) => (vcCats && typeof vcCats === 'object' && vcCats[g.id]) || g.title;
    const tx = (key, values, extra) => (
        <Trans t={t} i18nKey={key} values={values} components={{ b: <b />, q: <bdi dir="ltr" />, ...extra }} />
    );
    const [group, setGroup] = useState('all');
    // Arabic / Hindi phrases come from the ar-SA / hi-IN voice models (live since 2026-10-07).
    const languages = VOICE_COMMANDS.languages || {};
    const [lang, setLang] = useState('en');
    const L = lang === 'en' ? null : languages[lang];
    const phrasesFor = (cmd) => (L ? (L.say[cmd.say[0]] || []) : cmd.say);
    const groups = VOICE_COMMANDS.categories;
    const shown = group === 'all' ? groups : groups.filter((g) => g.id === group);

    const comingSoonCount = groups.reduce((n, g) => n + g.commands.filter((c) => c.comingSoon).length, 0);

    return (
        <Box>
            <Alert severity="info" variant="outlined" sx={{ mb: 3, borderRadius: 2 }}>
                <Typography variant="subtitle2" fontWeight={700}>{t('ref.langsTitle')}</Typography>
                <Typography variant="body2">
                    {tx('ref.langsBody', { p1: 'Alexa, ask Muslim Companion…' })}
                </Typography>
                {comingSoonCount > 0 && (
                    <Typography variant="body2" sx={{ mt: 0.75 }}>
                        {tx('ref.soonNote')}
                    </Typography>
                )}
            </Alert>
            {Object.keys(languages).length > 0 && (
                <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" justifyContent="center" sx={{ mb: 2 }}>
                    <Chip label={t('ref.english')} onClick={() => setLang('en')} color={lang === 'en' ? 'secondary' : 'default'} variant={lang === 'en' ? 'filled' : 'outlined'} />
                    {Object.entries(languages).map(([code, l]) => (
                        <Chip key={code} label={`${l.title}${l.comingSoon ? t('ref.soonSuffix') : ''}`} onClick={() => setLang(code)} color={lang === code ? 'secondary' : 'default'} variant={lang === code ? 'filled' : 'outlined'} />
                    ))}
                </Stack>
            )}
            {L && (
                <Alert severity="info" variant="outlined" sx={{ mb: 3, borderRadius: 2 }}>
                    <Typography variant="body2">
                        {tx('ref.langNote', { title: L.title, lang: t(lang === 'ar' ? 'ref.langAr' : 'ref.langHi'), name: L.invocation }, { n: <b dir={L.dir} /> })}
                    </Typography>
                </Alert>
            )}
            <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" justifyContent="center" sx={{ mb: 4 }}>
                <Chip label={t('ref.all')} onClick={() => setGroup('all')} color={group === 'all' ? 'primary' : 'default'} variant={group === 'all' ? 'filled' : 'outlined'} />
                {groups.map((g) => (
                    <Chip key={g.id} label={catTitle(g)} onClick={() => setGroup(g.id)} color={group === g.id ? 'primary' : 'default'} variant={group === g.id ? 'filled' : 'outlined'} />
                ))}
            </Stack>

            {shown.map((g) => (
                <Box key={g.id} sx={{ mb: 5 }}>
                    <Typography variant="h5" component="h3" sx={{ mb: 2, fontWeight: 600, textAlign: 'start' }}>{catTitle(g)}</Typography>
                    <Grid container spacing={2.5}>
                        {[...g.commands].sort((a, b) => Number(Boolean(a.comingSoon)) - Number(Boolean(b.comingSoon))).map((cmd) => (
                            <Grid item xs={12} sm={6} md={4} key={cmd.say[0]}>
                                <Card elevation={1} sx={{ height: '100%', borderRadius: 2, ...(cmd.comingSoon ? { opacity: 0.8, borderStyle: 'dashed', borderWidth: 1, borderColor: 'warning.light' } : {}) }}>
                                    <CardContent>
                                        {phrasesFor(cmd).map((s, i) => (
                                            <Box key={s} sx={{ mb: 0.75 }}>
                                                <Typography variant="subtitle1" fontWeight={600} dir={L ? L.dir : 'ltr'} lang={L ? undefined : 'en'} sx={{ lineHeight: 1.35, textAlign: 'start' }}>
                                                    <Box component="span" sx={{ color: theme.palette.primary.main }}>“</Box>{s}<Box component="span" sx={{ color: theme.palette.primary.main }}>”</Box>
                                                </Typography>
                                                {!L && tr(cmd)?.say?.[i] && (
                                                    <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'start' }}>{tr(cmd).say[i]}</Typography>
                                                )}
                                            </Box>
                                        ))}
                                        <Typography variant="body2" color="text.secondary" sx={{ mt: 1, textAlign: 'start' }}>{tr(cmd)?.does || cmd.does}</Typography>
                                        <Stack direction="row" spacing={0.75} useFlexGap flexWrap="wrap" sx={{ mt: 1.25 }}>
                                            {(cmd.comingSoon || L?.comingSoon) && <Chip size="small" color="warning" label={tr(cmd)?.soonNote || cmd.soonNote || t('ref.comingSoon')} />}
                                            {cmd.screen && <Chip size="small" label={t('ref.showsOnShow')} />}
                                            {!cmd.say.some((x) => /Muslim Companion/i.test(x)) && <Chip size="small" variant="outlined" label={t('ref.whilePlaying')} />}
                                            {cmd.caution && <Chip size="small" color="warning" variant="outlined" label={t('ref.turnsOff')} />}
                                        </Stack>
                                    </CardContent>
                                </Card>
                            </Grid>
                        ))}
                    </Grid>
                    {g.tip && <Typography variant="body2" color="text.secondary" sx={{ mt: 1.5 }}>{t('ref.tip', { tip: g.tip })}</Typography>}
                </Box>
            ))}

            <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 2 }}>
                {tx('ref.footer', { p1: 'Alexa, open Muslim Companion' })}
            </Typography>
        </Box>
    );
}
